static VALUE rb_QWidget_ctor(int argc, VALUE* argv, VALUE self) {
  (void)argv;
  if (argc == 0) {
    Rb_QWidget* p = new Rb_QWidget();
    qt6rb::attach(self, p, false);
    p->qt6rb_set_self(self);
    return self;
  }
  if (argc == 1) {
    Rb_QWidget* p = new Rb_QWidget(static_cast<QWidget*>(qt6rb::unwrap_release(argv[0], &cls_QWidget)));
    qt6rb::attach(self, p, false);
    p->qt6rb_set_self(self);
    return self;
  }
  if (argc == 2) {
    Rb_QWidget* p = new Rb_QWidget(static_cast<QWidget*>(qt6rb::unwrap_release(argv[0], &cls_QWidget)), QFlags<Qt::WindowType>::fromInt(NUM2INT(argv[1])));
    qt6rb::attach(self, p, false);
    p->qt6rb_set_self(self);
    return self;
  }
  rb_raise(rb_eArgError, "wrong number of arguments for QWidget#initialize (%d)", argc);
}
